    [ProrateInApplication] NVARCHAR(MAX) NULL,
    [IsEditable] NVARCHAR(MAX) NULL,
    [IsSystem] NVARCHAR(MAX) NULL,
    [FieldType] NVARCHAR(400) NULL,
    [ExtraCharge] NVARCHAR(MAX) NULL,
    [DisplayType] NVARCHAR(255) NULL,
    [Id] NVARCHAR(255) NULL,
    [Order] NVARCHAR(255) NULL,
    [Access] NVARCHAR(400) NULL,
    [AdminOnly] NVARCHAR(MAX) NULL,
    [MemberOnly] NVARCHAR(MAX) NULL,
    [IsBuiltIn] NVARCHAR(MAX) NULL,
    [AllowedValues] NVARCHAR(MAX) NULL,
    [SystemCode] NVARCHAR(255) NULL,
    [SupportSearch] NVARCHAR(MAX) NULL,
    [Description] NVARCHAR(255) NULL,
    [ExistsInLevels] NVARCHAR(MAX) NULL,
    [__mj_integration_SyncStatus] NVARCHAR(50) NOT NULL DEFAULT 'Active',
    [__mj_integration_LastSyncedAt] DATETIMEOFFSET NULL,
    [__mj_integration_LastSyncedSnapshot] NVARCHAR(MAX) NULL,
    [__mj_integration_SyncMessage] NVARCHAR(MAX) NULL,
    [__mj_integration_ContentHash] NVARCHAR(64) NULL,
    [__mj_integration_CustomOverflow] NVARCHAR(MAX) NULL,
    [__mj_integration_ExternalVersion] NVARCHAR(255) NULL,
