    [RegistrationTypeId] NVARCHAR(255) NULL,
    [ShowToPublic] NVARCHAR(MAX) NULL,
    [IsPaid] NVARCHAR(MAX) NULL,
    [RegistrationFields] NVARCHAR(MAX) NULL,
    [IsCheckedIn] NVARCHAR(MAX) NULL,
    [Event] NVARCHAR(MAX) NULL,
    [IsGuestRegistration] NVARCHAR(MAX) NULL,
    [Contact] NVARCHAR(MAX) NULL,
    [Id] NVARCHAR(255) NULL,
    [Url] NVARCHAR(MAX) NULL,
    [RecreateInvoice] NVARCHAR(MAX) NULL,
    [Organization] NVARCHAR(255) NULL,
    [RegistrationType] NVARCHAR(MAX) NULL,
    [OnWaitlist] NVARCHAR(MAX) NULL,
    [RegistrationDate] NVARCHAR(MAX) NULL,
    [DisplayName] NVARCHAR(255) NULL,
    [ParentRegistration] NVARCHAR(MAX) NULL,
    [PaidSum] NVARCHAR(255) NULL,
    [Status] NVARCHAR(400) NULL,
    [__mj_integration_SyncStatus] NVARCHAR(50) NOT NULL DEFAULT 'Active',
    [__mj_integration_LastSyncedAt] DATETIMEOFFSET NULL,
    [__mj_integration_LastSyncedSnapshot] NVARCHAR(MAX) NULL,
    [__mj_integration_SyncMessage] NVARCHAR(MAX) NULL,
    [__mj_integration_ContentHash] NVARCHAR(64) NULL,
    [__mj_integration_CustomOverflow] NVARCHAR(MAX) NULL,
    [__mj_integration_ExternalVersion] NVARCHAR(255) NULL,
    [__mj_integration_LastSeenModifiedValue] NVARCHAR(255) NULL,
    [__mj_integration_LastReconciledAt] DATETIMEOFFSET NULL,
    [__mj_integration_LastWriterDirection] NVARCHAR(10) NULL,
    [__mj_integration_IsTombstoned] BIT NOT NULL DEFAULT 0,
    [__mj_integration_DeletedDetectedAt] DATETIMEOFFSET NULL
);

